"""RAMBLA studio theme: charcoal panels with restrained aqua and violet accents and explicit gallery controls."""
CSS = r'''<style id="rambla-studio-v10">
:root{--bg:#0b0e10;--p:#13171b;--p2:#171c21;--line:#2b323a;--ink:#edf0f4;--muted:#9aa4b2;--lime:#54bd9d;--cyan:#69cbb0}
body{background:#0b0e10;color:var(--ink);font-size:14px;line-height:1.5}
main{max-width:1520px;padding:24px 32px;margin:auto}.top{gap:18px}.top h1{letter-spacing:-.045em;font-weight:750}.grid{gap:18px}
.panel,.rail,.stage,.tray{background:var(--p);border:1px solid #2b323a;border-radius:16px;padding:20px;box-shadow:0 8px 28px #00000018}
.panel{margin-top:18px}.rail,.tray{background:#111519}.stage{background:linear-gradient(150deg,#181d22,#14191e)}.rail{top:18px;height:calc(100vh - 36px)}
button{border-radius:12px;padding:10px 14px;background:#20272e;border-color:#36414b;font-weight:600;transition:background .16s,border-color .16s,box-shadow .16s}
button:hover:not(:disabled){background:#2c383e;border-color:#63c3a5}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #b3bdff;outline-offset:3px}
button.primary,button.active{background:linear-gradient(125deg,#319d83,#695199);border-color:#67b6a3;color:#fff;box-shadow:0 4px 16px #5553b329}button.ghost{background:#1b2228}button:disabled{opacity:.4}
.rail>.row{gap:6px;margin:16px 0}.rail>.row button{font-size:11px;padding:7px 10px}.phrase{margin:8px 0;padding:13px 14px;border:1px solid transparent;background:#1b2027;font-size:13px;line-height:1.5;font-weight:500}.phrase small{font-size:10px;letter-spacing:.04em;margin-bottom:5px;color:#b5badb}.phrase.active small{color:#e0e4ff}.phrase.active{border-color:#a1a7ff}
#active>h2{font-size:23px;line-height:1.4;font-weight:600;letter-spacing:-.025em;margin:10px 0 24px}#active>small{font-size:11px;color:#a9add0}#active h3{font-size:14px;margin-top:18px}#active ol{padding-left:24px}#active li{margin:14px 0;line-height:1.65}.searchDiagnostics{margin:20px 0;color:var(--muted)}.searchDiagnostics pre{background:#10151a;border-radius:12px;padding:16px}
.managementV2,.projectbar{background:#12171c;border:1px solid #3c4266;border-radius:14px;padding:12px}.projectbar b{color:#bac6ff}.searchGroupsV5>div{background:#1b2228;border-radius:16px;padding:18px;gap:12px}.searchGroupsV5{gap:16px}.searchGroupsV5 b{color:#e3e6ff}.toolsV5{padding-top:16px}.directorV5 select,input{background:#141a20;color:var(--ink);border:1px solid #36414b;border-radius:10px}
.shelfHead{border-top:1px solid #484d704f;padding-top:28px;margin-top:30px!important;margin-bottom:8px}.shelfHead h3{font-size:13px;letter-spacing:.09em;color:#eceeff}.providerProgressV9{margin:10px 0 16px;font-size:12px}.providerProgressV9 progress{accent-color:#9a9bff}
.galleryShellV9{grid-template-columns:48px minmax(0,1fr) 48px;gap:12px;align-items:center}.galleryShellV9>.cards{width:100%;padding:0}.galleryNavV10{width:48px;height:64px;padding:0;display:grid;place-items:center;background:#202930;border:1px solid #6976b9;border-radius:18px;box-shadow:0 6px 18px #13152a40}.galleryNavV10 svg{width:24px;height:24px}.galleryNavV10:hover:not(:disabled){background:#5665ab;box-shadow:0 6px 22px #485ab04d}.galleryNavV10:disabled{opacity:.23;background:#272d49;box-shadow:none}
.galleryBarV9{gap:14px;flex-wrap:wrap;margin:18px 60px 26px;align-items:center}.galleryPageV10{color:#f0f1ff;font-size:12px;font-variant-numeric:tabular-nums}.galleryPageV10 small{display:block;font-size:10px;margin-top:3px}.gallerySearchV10{background:#3e4675;border:1px solid #7784d0;padding:10px 14px;font-size:12px;color:#e9edff}.galleryRoundV10{font-size:10px;color:#9aa4b2}.galleryBarV9 details{font-size:11px}.galleryKeywordsV9{background:#171d23;border-color:#505882}.galleryKeywordsV9 input{background:#10161b;border-color:#505882}
.portraitSocialV6{background:#171d23!important;border-color:#4c5279;border-radius:16px!important;box-shadow:0 6px 16px #12142a24}.portraitSocialV6>.copy{padding:12px 10px!important;gap:10px}.portraitSocialV6 .copy>a,.portraitSocialV6 .copy>button{background:#3b4269;border-color:#5b6696;border-radius:9px;color:#edf0ff;min-height:34px}.portraitSocialV6 .copy>a:hover{background:#4d5a89;border-color:#899cea}.portraitSocialV6 .copy>b{font-size:12px;font-weight:600}.portraitSocialV6>img,.portraitSocialV6>video{background:#0c1014}.socialMissingV7{background:#171d23;color:#b7bfdf}
.card{--selected-card:#f1d85a;position:relative;border-radius:16px;background:#171c22;border-color:#454e74}.card.active{border:2px solid var(--selected-card)!important;background:#35344a;box-shadow:0 0 0 3px #f1d85a35,0 12px 30px #090b1f55}.card.active .select{background:var(--selected-card);border-color:#fff0a0;color:#211f12}.selectedBadgeV27{position:absolute;z-index:3;top:10px;right:10px;padding:5px 9px;border-radius:999px;background:var(--selected-card);color:#211f12;font-size:10px;font-weight:900;letter-spacing:.06em;box-shadow:0 4px 14px #090b1f88}.tray>button{width:100%;margin-top:12px}.tray>b,.rail>b{font-size:11px;letter-spacing:.12em;color:#bfc8f4}.chip{background:#30365b;border-color:#6877bb}dialog,#gifLightboxV9{background:#171c22;border-color:#6571a6;border-radius:22px;box-shadow:0 20px 90px #08091f88}dialog::backdrop{background:#0c1021b3;backdrop-filter:blur(6px)}.analysis-scroll{background:#11161b;border-radius:12px}#drop{border-color:#6674a0;border-radius:16px}
.shelfHead h3{display:flex;align-items:center;gap:9px;font-size:14px;letter-spacing:.075em;color:#f4f5ff}.shelfHead h3::before{content:'';width:8px;height:8px;border-radius:50%;background:linear-gradient(135deg,#69cbb0,#9d79ff);box-shadow:0 0 0 4px #7784d020}.providerHeaderV25{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.providerHeaderV25>h3{margin-right:auto}.providerControlsV25{margin:0!important;justify-content:center}.galleryPageV10{display:flex;align-items:center;gap:7px;font-size:11px}.galleryPageV10 small{display:inline;margin:0;color:#9299bc}.gallerySearchV10{padding:8px 12px}.galleryRoundV10{white-space:nowrap}
.cards{align-items:start}.card{align-self:start}.card:not(.portraitSocialV6)>img,.card:not(.portraitSocialV6)>video{display:block;width:100%;height:auto!important;max-height:360px;aspect-ratio:auto;object-fit:contain;background:#0c1014}.card .copy{display:grid;gap:7px;padding:12px}.card .copy>b{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:13px;line-height:1.4}.card .copy>small{font-size:10px;line-height:1.45}.sourceButtonV9{display:inline-flex!important;align-items:center;justify-content:center;width:max-content;min-height:34px;padding:7px 12px!important;border:1px solid #6574ad;border-radius:10px;background:#343b62;color:#f0f2ff!important;text-decoration:none;font-size:11px;font-weight:750}.sourceButtonV9:hover{background:#4b5688;border-color:#93a1eb}
.projectTitleV25{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.projectTitleV25>span{font-size:10px;font-weight:850;letter-spacing:.14em;color:#aeb6df}.projectNameV25{min-width:min(440px,70vw);padding:4px 2px!important;border:0!important;border-bottom:1px solid transparent!important;border-radius:0!important;background:transparent!important;color:#f4f5ff!important;font-size:24px!important;font-weight:720;letter-spacing:-.03em}.projectNameV25:hover,.projectNameV25:focus{border-bottom-color:#7d89d4!important;outline:0}.projectNameV25:disabled{opacity:.55}
.visualPlanBoxV26{margin:14px 0;padding:0;border:1px solid #485276;border-radius:14px;background:#10151a}.visualPlanBoxV26>summary{cursor:pointer;padding:11px 14px;font-size:12px;font-weight:850;letter-spacing:.04em;color:#dce2ff}.visualPlanBoxV26>div{padding:0 14px 13px;border-top:1px solid #3d4566}.visualPlanBoxV26 h3{margin-top:13px}
*{scrollbar-width:thin;scrollbar-color:#565e88 #141a20}@media(max-width:1100px){main{padding:16px}.galleryShellV9{grid-template-columns:42px minmax(0,1fr) 42px;gap:8px}.galleryNavV10{width:42px;height:56px}.galleryBarV9{margin-left:0;margin-right:0}}@media(prefers-reduced-motion:reduce){button{transition:none}}
.brandHeaderV41{display:flex;align-items:center;gap:16px}.brandWordmarkV41{width:min(245px,36vw);height:auto;display:block}.brandTextV41{display:flex;align-items:center;gap:7px}.brandProductV41{font-size:12px;font-weight:850;letter-spacing:.13em;color:#cdd3f4}@media(max-width:700px){.brandHeaderV41{align-items:flex-start;flex-direction:column}.brandWordmarkV41{width:min(280px,76vw)}}
</style>'''
